#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,m;scanf("%d %d",&n,&m);
vector<vector<int>>g(n+1);vector<int>indeg(n+1,0);
for(int i=0;i<m;++i){int a,b;scanf("%d %d",&a,&b);g[a].push_back(b);++indeg[b];}
queue<int>q;for(int i=1;i<=n;++i)if(indeg[i]==0)q.push(i);
int cnt=0;
while(!q.empty()){int u=q.front();q.pop();++cnt;
for(int v:g[u])if(--indeg[v]==0)q.push(v);}
printf("%s\n",cnt==n?"YES":"NO");return 0;}

